    # Step 1: Convert the input string to uppercase
    input_string = input_string.upper()

    # Step 2: Replace all vowels with their corresponding harmonized vowels
    harmonized_string = ''
    for char in input_string:
        if char in 'AEIOU':
            if char == 'A':
                harmonized_string += '4'
            elif char == 'E':
                harmonized_string += '3'
            elif char == 'I':
                harmonized_string += '1'
            elif char == 'O':
                harmonized_string += '0'
            elif char == 'U':
                harmonized_string += '2'
        else:
            harmonized_string += char

    # Step 3: Verify the result
    print(f'[INFO] Step 1: Input string is {input_string}')
    print(f'[INFO] Step 2: Harmonized string is {harmonized_string}')

